def _desktop_icon():
    """Largest frame of the desktop app icon, so phone and PC share one logo."""
    import sys
    from pathlib import Path
    from PySide6.QtGui import QImageReader
    base = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent.parent))
    reader = QImageReader(str(base / "assets" / "app.ico"))
    best = None
    for index in range(max(1, reader.imageCount())):
        reader.jumpToImage(index)
        frame = reader.read()
        if not frame.isNull() and (best is None or frame.width() > best.width()):
            best = frame
    return best


def _icon_png(size):
    from PySide6.QtCore import QByteArray, QBuffer, QIODevice, Qt
    from PySide6.QtGui import QImage, QPainter
    from PySide6.QtSvg import QSvgRenderer
    source = _desktop_icon()
    if source is not None:
        image = source.convertToFormat(QImage.Format_ARGB32).scaled(
            size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
    else:  # Missing asset: keep the previous drawn icon rather than none.
        image = QImage(size, size, QImage.Format_ARGB32)
        image.fill(Qt.transparent)
        painter = QPainter(image)
        QSvgRenderer(ICON.encode('utf-8')).render(painter)
        painter.end()
    data = QByteArray()
    buffer = QBuffer(data)
    buffer.open(QIODevice.WriteOnly)
    image.save(buffer, 'PNG')
    return bytes(data)

import hashlib as _hashlib
APP_VERSION = _hashlib.sha256((HTML + CSS + JS).encode("utf-8")).hexdigest()[:12]
JS = JS.replace("__APP_VERSION__", APP_VERSION)
# Lock-screen artwork inline: iOS sometimes shows a blank white tile when it
# has to fetch the icon while the page is in the background.
import base64 as _base64
JS = JS.replace("__PIP_ART__", "data:image/png;base64," + _base64.b64encode(_icon_png(256)).decode("ascii"))

ASSETS = {
    "/": ("text/html; charset=utf-8", HTML),
    # Same page, only 目前持倉: added to the Home Screen as a Safari bookmark
    # (the home-screen web app cannot use Picture-in-Picture on iPhone).
    "/pip": ("text/html; charset=utf-8", HTML),
    # Polled when the phone app comes back to the front: a new version reloads.
    "/version.json": ("application/json; charset=utf-8", '{"v": "%s"}' % APP_VERSION),
    "/app.css": ("text/css; charset=utf-8", CSS),
    "/app.js": ("text/javascript; charset=utf-8", JS),
    "/icon-180.png": ("image/png", _icon_png(180)),
    "/icon-192.png": ("image/png", _icon_png(192)),
    "/icon-512.png": ("image/png", _icon_png(512)),
    # No fetch handler/cache, credentials or pending trading command in this worker.
    "/sw.js": ("text/javascript; charset=utf-8", '''self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('push',event=>{let data={};try{data=event.data.json();if(!data||typeof data!=='object')data={};}catch(error){}
const stale=typeof data.expires==='number'&&data.expires*1000<Date.now();
event.waitUntil(self.registration.showNotification(String(data.title||'對沖小幫手').slice(0,80),{
body:stale?'較早的提醒，請開啟消息查看最新狀況。':String(data.body||'').slice(0,300),
icon:'/icon-192.png',badge:'/icon-192.png',tag:String(data.tag||'helper-news').slice(0,80),data:{page:'news'}}));});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{
const pages=await clients.matchAll({type:'window',includeUncontrolled:true});
const page=pages.find(p=>new URL(p.url).origin===self.location.origin);
if(page){await page.focus();page.postMessage({type:'open-news'});}else await clients.openWindow('/#news');})());});'''),
    "/manifest.webmanifest": ("application/manifest+json", '{"id":"/","name":"對沖小幫手","short_name":"對沖小幫手","start_url":"/","scope":"/","display":"standalone","background_color":"#09090c","theme_color":"#101015","icons":[{"src":"/icon-192.png","sizes":"192x192","type":"image/png","purpose":"any"},{"src":"/icon-512.png","sizes":"512x512","type":"image/png","purpose":"any"}]}'),
}
